            }
        }
        return (18);
    }

    /**
     * @dev Deprecated. This function has issues similar to the ones found in
     * {IERC20-approve}, and its usage is discouraged.
     *
     * Whenever possible, use {safeIncreaseAllowance} and
     * {safeDecreaseAllowance} instead.
     */
    function safeApprove(IERC20 token, address spender, uint256 value) internal {
        // safeApprove should only be called when setting an initial or zero allowance,
        // or when resetting it to zero. To increase and decrease it, use
        // 'safeIncreaseAllowance' and 'safeDecreaseAllowance'
        callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, value));
    }

    /**
     * @dev Imitates a Solidity high-level call (i.e. a regular function call to a contract), relaxing the requirement
     * on the return value: the return value is optional (but if data is returned, it must not be false).
     * @param token The token targeted by the call.
     * @param data The call data (encoded using abi.encode or one of its variants).
     */
    function callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20.SafeERC20FailedOperation(address(token));
        }
    }

    function cast(IERC20[] memory tokens) internal pure returns (BetterIERC20[] memory betterTokens) {
        betterTokens = new BetterIERC20[](tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            betterTokens[i] = BetterIERC20(address(tokens[i]));
        }
    }
}

// contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookPullLib.sol

/**
 * @title UniswapV4SingleStandardExchangeBufferConstantProductHookPullLib
 * @notice ERC-20 + Permit2 pull helpers for dual-currency pool-order deposits.
 */
library UniswapV4SingleStandardExchangeBufferConstantProductHookPullLib {
    using BetterSafeERC20 for IERC20;

    address internal constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    error InvalidPermit2Data();

    function pullErc20Dual(address currency0, address currency1, uint256 amount0, uint256 amount1)
        external
    {
        IERC20(currency0).safeTransferFrom(msg.sender, address(this), amount0);
        IERC20(currency1).safeTransferFrom(msg.sender, address(this), amount1);
    }

    function pullErc20Single(address tokenIn, uint256 amountIn) external {
        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);
    }

    function pullPermit2SignatureDual(
        address currency0,
        address currency1,
        uint256 amount0,
        uint256 amount1,
        bytes calldata permit2Data
    ) external {
        (ISignatureTransfer.PermitBatchTransferFrom memory permit, bytes memory signature) =
            abi.decode(permit2Data, (ISignatureTransfer.PermitBatchTransferFrom, bytes));
        if (permit.permitted.length != 2) revert InvalidPermit2Data();
        if (permit.permitted[0].token != currency0 || permit.permitted[1].token != currency1) {
            revert InvalidPermit2Data();
        }
        ISignatureTransfer.SignatureTransferDetails[] memory details =
            new ISignatureTransfer.SignatureTransferDetails[](2);
        details[0] =
            ISignatureTransfer.SignatureTransferDetails({to: address(this), requestedAmount: amount0});
        details[1] =
            ISignatureTransfer.SignatureTransferDetails({to: address(this), requestedAmount: amount1});
        ISignatureTransfer(PERMIT2).permitTransferFrom(permit, details, msg.sender, signature);
    }

    function pullPermit2SignatureSingle(address tokenIn, uint256 amountIn, bytes calldata permit2Data)
        external
    {
        (ISignatureTransfer.PermitTransferFrom memory permit, bytes memory signature) =
            abi.decode(permit2Data, (ISignatureTransfer.PermitTransferFrom, bytes));
        if (permit.permitted.token != tokenIn) revert InvalidPermit2Data();
        ISignatureTransfer.SignatureTransferDetails memory details = ISignatureTransfer
            .SignatureTransferDetails({to: address(this), requestedAmount: amountIn});
        ISignatureTransfer(PERMIT2).permitTransferFrom(permit, details, msg.sender, signature);
    }

    function pullPermit2AllowanceDual(
        address currency0,
        address currency1,
        uint256 amount0,
        uint256 amount1
    ) external {
        IAllowanceTransfer(PERMIT2).transferFrom(
            msg.sender, address(this), uint160(amount0), currency0
        );
        IAllowanceTransfer(PERMIT2).transferFrom(
            msg.sender, address(this), uint160(amount1), currency1
        );
    }

    function pullPermit2AllowanceSingle(address tokenIn, uint256 amountIn) external {
        IAllowanceTransfer(PERMIT2).transferFrom(
            msg.sender, address(this), uint160(amountIn), tokenIn
        );
    }
}

// contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookWithdrawTarget.sol

/**
 * @title UniswapV4SingleStandardExchangeBufferConstantProductHookWithdrawTarget
 * @notice Product logic only: CP hooks, liquidity, SE In/Out, product views.
 * @dev LP ERC-20, IBasicVault, IStandardVault are cut as shared facets on the diamond.
 *      LP supply/balances use ERC20Repo; vaultTokens/reserves use MultiAssetBasicVaultRepo
 *      (pair reserve accounting = virtual SE claim; raw = face inventory).
 */
abstract contract UniswapV4SingleStandardExchangeBufferConstantProductHookWithdrawTarget {
    using BetterSafeERC20 for IERC20;

    event Deposit(address indexed sender, address indexed to, uint256 amount0, uint256 amount1, uint256 used0, uint256 used1, uint256 lpAmount);
    event DepositSingle(address indexed sender, address indexed to, address tokenIn, uint256 amountIn, uint256 lpAmount);
    event Withdraw(address indexed sender, address indexed to, uint256 lpAmount, uint256 amount0, uint256 amount1);
    event WithdrawSingle(address indexed sender, address indexed to, uint256 lpAmount, address tokenOut, uint256 amountOut);
    event WithdrawSeShares(
        address indexed sender, address indexed to, uint256 lpAmount, uint256 amountRaw, uint256 amountSe
    );
    event ZapSwap(address indexed sender, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);

    address internal constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    error ZeroAddress();
    error ZeroAmount();
    error NotPoolManager();
    error TokenNotInVaultTokens();
    error SameToken();
    error RawIsSE();
    error NotLive();
    error NotZapEligible();
    error InvalidToken();
    error DeadlineExpired();
    error InsufficientLpOut();
    error InsufficientTokenOut();
    error AlreadyInitialized();
    error Reentrancy();
    error LiquidityNotAllowed();
    error InvalidPoolToken();
    error InvalidPoolFee();
    error HookNotImplemented();
    error UnsupportedRoute();

    modifier nonReentrant() {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (l.reentrancyStatus == UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.ENTERED) revert Reentrancy();
        l.reentrancyStatus = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.ENTERED;
        _;
        l.reentrancyStatus = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.NOT_ENTERED;
    }

    modifier onlyLiquidityOwner() {
        UniswapV4HookOwnerOnlyLiquidityLib.enforce(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().ownerOnlyLiquidity);
        _;
    }

    /* ---------------------------------------------------------------------- */
    /*                              bindings / views                          */
    /* ---------------------------------------------------------------------- */

    function poolManager() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().poolManager;
    }

    function feeOracle() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().feeOracle;
    }

    function permit2() public pure returns (address) {
        return PERMIT2;
    }

    function standardExchange() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().standardExchange;
    }

    function pairToken() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().pairToken;
    }

    function rawToken() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken;
    }

    function currency0() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency0;
    }

    function currency1() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency1;
    }

    function rawReserve() public view returns (uint256) {
        return IERC20(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken).balanceOf(address(this));
    }

    function seClaimSupply() public view returns (uint256) {
        return _seClaim();
    }

    function reserveCurrency0() public view returns (uint256) {
        return _reserveOfCurrency(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency0);
    }

    function reserveCurrency1() public view returns (uint256) {
        return _reserveOfCurrency(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency1);
    }

    function isLive() public view returns (bool) {
        return _isLive();
    }

    function isZapEligible() public view returns (bool) {
        return _isZapEligible();
    }

    function tradingFeePercent() public pure returns (uint256) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.TRADING_FEE_PERCENT;
    }

    function tradingFeeDenominator() public pure returns (uint256) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.TRADING_FEE_DENOMINATOR;
    }

    function dexSwapFeeAndFeeTo() public view returns (address feeTo_, uint256 dexFeeWad) {
        (IFeeCollectorProxy ft, uint256 wad) =
            IVaultFeeOracleQuery(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().feeOracle).dexSwapFeeAndFeeToOfVault(address(this));
        return (address(ft), wad);
    }

    function kLast() public view returns (uint256) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().kLast;
    }

    function _seClaim() internal view returns (uint256) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 seBal = IERC20(l.standardExchange).balanceOf(address(this));
        if (seBal == 0) return 0;
        return IStandardExchangeIn(l.standardExchange).previewExchangeIn(
            IERC20(l.standardExchange), seBal, IERC20(l.pairToken)
        );
    }

    function _reserveOfCurrency(address c) internal view returns (uint256) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (c == l.rawToken) return IERC20(l.rawToken).balanceOf(address(this));
        if (c == l.pairToken) return _seClaim();
        return 0;
    }

    function _isLive() internal view returns (bool) {
        return reserveCurrency0() > 0 && reserveCurrency1() > 0;
    }

    function _isZapEligible() internal view returns (bool) {
        return _isLive() && ERC20Repo._totalSupply() > UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.MINIMUM_LIQUIDITY;
    }

    /// @dev Keep MultiAssetBasicVaultRepo reserves aligned with product book (raw face × virtual pair).
    function _syncReserves() internal {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        MultiAssetBasicVaultRepo._updateReserve(IERC20(l.rawToken), IERC20(l.rawToken).balanceOf(address(this)));
        MultiAssetBasicVaultRepo._updateReserve(IERC20(l.pairToken), _seClaim());
    }

    function _mintLp(address to, uint256 amount) internal {
        if (amount == 0) return;
        ERC20Repo._mint(to, amount);
    }

    function _burnLp(address from, uint256 amount) internal {
        ERC20Repo._burn(from, amount);
    }

    function _onlyPoolManager() internal view {
        if (msg.sender != UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().poolManager) revert NotPoolManager();
    }

    function _requireLive() internal view {
        if (!_isLive()) revert NotLive();
    }

    function _requireZapEligible() internal view {
        if (!_isZapEligible()) revert NotZapEligible();
    }

    function _requireNonZero(uint256 amount) internal pure {
        if (amount == 0) revert ZeroAmount();
    }

    function _requireDeadline(uint256 deadline) internal view {
        if (block.timestamp > deadline) revert DeadlineExpired();
    }

    function _decimalsOf(address token) internal view returns (uint8) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (token == l.currency0) return l.decimalsCurrency0;
        if (token == l.currency1) return l.decimalsCurrency1;
        revert InvalidToken();
    }

    function _wadProduct() internal view returns (uint256) {
