    function _quoteExactOut(bool zeroForOne, uint256 amountOut) internal view returns (uint256 amountIn) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        bool rawIn = zeroForOne == _zeroForOneIsRawIn();
        uint256 rawBal = IERC20(l.rawToken).balanceOf(address(this));
        uint256 seClaim = _seClaim();
        if (rawIn) {
            // need pair out → raw in
            uint256 claimOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(amountOut, _decimalsOf(l.pairToken));
            uint256 rInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawBal, _decimalsOf(l.rawToken));
            uint256 rOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(seClaim, _decimalsOf(l.pairToken));
            amountIn = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadCeil(UniswapV4SingleStandardExchangeBufferConstantProductHookMath.purchaseQuote(claimOutN, rInN, rOutN), _decimalsOf(l.rawToken));
