            uint256 rInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(seClaim, _decimalsOf(l.pairToken));
            uint256 rOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawBal, _decimalsOf(l.rawToken));
            uint256 claimInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.purchaseQuote(rawOutN, rInN, rOutN);
            uint256 claimIn = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadCeil(claimInN, _decimalsOf(l.pairToken));
            amountIn = _invertBufferClaimIn(claimIn);
        }
    }
    function _routeZeroForOne(address tokenIn, address tokenOut) internal view returns (bool) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
