        l.currency0 = currency0_;
        l.currency1 = currency1_;
        l.decimalsCurrency0 = dec0;
        l.decimalsCurrency1 = dec1;
        l.bindingsInitialized = true;
        l.reentrancyStatus = NOT_ENTERED;
    }
}

