     */
    /// forge-lint: disable-next-line(mixed-case-function)
    function _toIERC20(address[] memory addresses) internal pure returns (BetterIERC20[] memory erc20s) {
        erc20s = new BetterIERC20[](addresses.length);
        for (uint256 i = 0; i < addresses.length; i++) {
            erc20s[i] = BetterIERC20(addresses[i]);
