        (bool success, bytes memory encodedName) = address(asset_).staticcall(abi.encodeCall(IERC20Metadata.name, ()));
        if (success && encodedName.length >= 32) {
            return abi.decode(encodedName, (string));
        }
        return "ERC20 Token";
    }

    function safeSymbol(IERC20Metadata asset_) internal view returns (string memory) {
        (bool success, bytes memory encodedSymbol) =
            address(asset_).staticcall(abi.encodeCall(IERC20Metadata.symbol, ()));
        if (success && encodedSymbol.length >= 32) {
            return abi.decode(encodedSymbol, (string));
        }
        return "ERC20";
    }

    /**
     * @dev Attempts to fetch the asset decimals. A return value of false indicates that the attempt failed in some way.
     */
    function safeDecimals(IERC20Metadata asset_) internal view returns (uint8) {
        (bool success, bytes memory encodedDecimals) =
            address(asset_).staticcall(abi.encodeCall(IERC20Metadata.decimals, ()));
        if (success && encodedDecimals.length >= 32) {
            uint256 returnedDecimals = abi.decode(encodedDecimals, (uint256));
            if (returnedDecimals <= type(uint8).max) {
                return (uint8(returnedDecimals));
            }
        }
        return (18);
    }

    /**
     * @dev Deprecated. This function has issues similar to the ones found in
     * {IERC20-approve}, and its usage is discouraged.
     *
     * Whenever possible, use {safeIncreaseAllowance} and
     * {safeDecreaseAllowance} instead.
     */
    function safeApprove(IERC20 token, address spender, uint256 value) internal {
        // safeApprove should only be called when setting an initial or zero allowance,
        // or when resetting it to zero. To increase and decrease it, use
        // 'safeIncreaseAllowance' and 'safeDecreaseAllowance'
        callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, value));
    }

    /**
     * @dev Imitates a Solidity high-level call (i.e. a regular function call to a contract), relaxing the requirement
     * on the return value: the return value is optional (but if data is returned, it must not be false).
     * @param token The token targeted by the call.
     * @param data The call data (encoded using abi.encode or one of its variants).
     */
    function callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20.SafeERC20FailedOperation(address(token));
        }
    }

    function cast(IERC20[] memory tokens) internal pure returns (BetterIERC20[] memory betterTokens) {
        betterTokens = new BetterIERC20[](tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            betterTokens[i] = BetterIERC20(address(tokens[i]));
        }
    }
}

// contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookPullLib.sol

/**
 * @title UniswapV4SingleStandardExchangeBufferConstantProductHookPullLib
 * @notice ERC-20 + Permit2 pull helpers for dual-currency pool-order deposits.
 */
library UniswapV4SingleStandardExchangeBufferConstantProductHookPullLib {
    using BetterSafeERC20 for IERC20;

    address internal constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    error InvalidPermit2Data();

    function pullErc20Dual(address currency0, address currency1, uint256 amount0, uint256 amount1)
        external
    {
        IERC20(currency0).safeTransferFrom(msg.sender, address(this), amount0);
        IERC20(currency1).safeTransferFrom(msg.sender, address(this), amount1);
    }

    function pullErc20Single(address tokenIn, uint256 amountIn) external {
        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);
    }

    function pullPermit2SignatureDual(
        address currency0,
        address currency1,
        uint256 amount0,
        uint256 amount1,
        bytes calldata permit2Data
    ) external {
        (ISignatureTransfer.PermitBatchTransferFrom memory permit, bytes memory signature) =
            abi.decode(permit2Data, (ISignatureTransfer.PermitBatchTransferFrom, bytes));
        if (permit.permitted.length != 2) revert InvalidPermit2Data();
        if (permit.permitted[0].token != currency0 || permit.permitted[1].token != currency1) {
            revert InvalidPermit2Data();
        }
        ISignatureTransfer.SignatureTransferDetails[] memory details =
            new ISignatureTransfer.SignatureTransferDetails[](2);
        details[0] =
            ISignatureTransfer.SignatureTransferDetails({to: address(this), requestedAmount: amount0});
        details[1] =
            ISignatureTransfer.SignatureTransferDetails({to: address(this), requestedAmount: amount1});
        ISignatureTransfer(PERMIT2).permitTransferFrom(permit, details, msg.sender, signature);
    }

    function pullPermit2SignatureSingle(address tokenIn, uint256 amountIn, bytes calldata permit2Data)
        external
    {
        (ISignatureTransfer.PermitTransferFrom memory permit, bytes memory signature) =
            abi.decode(permit2Data, (ISignatureTransfer.PermitTransferFrom, bytes));
        if (permit.permitted.token != tokenIn) revert InvalidPermit2Data();
        ISignatureTransfer.SignatureTransferDetails memory details = ISignatureTransfer
            .SignatureTransferDetails({to: address(this), requestedAmount: amountIn});
        ISignatureTransfer(PERMIT2).permitTransferFrom(permit, details, msg.sender, signature);
    }

    function pullPermit2AllowanceDual(
        address currency0,
        address currency1,
        uint256 amount0,
        uint256 amount1
    ) external {
        IAllowanceTransfer(PERMIT2).transferFrom(
            msg.sender, address(this), uint160(amount0), currency0
        );
        IAllowanceTransfer(PERMIT2).transferFrom(
            msg.sender, address(this), uint160(amount1), currency1
        );
    }

    function pullPermit2AllowanceSingle(address tokenIn, uint256 amountIn) external {
        IAllowanceTransfer(PERMIT2).transferFrom(
            msg.sender, address(this), uint160(amountIn), tokenIn
        );
    }
}

// contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookWithdrawTarget.sol

/**
 * @title UniswapV4SingleStandardExchangeBufferConstantProductHookWithdrawTarget
 * @notice Product logic only: CP hooks, liquidity, SE In/Out, product views.
 * @dev LP ERC-20, IBasicVault, IStandardVault are cut as shared facets on the diamond.
 *      LP supply/balances use ERC20Repo; vaultTokens/reserves use MultiAssetBasicVaultRepo
 *      (pair reserve accounting = virtual SE claim; raw = face inventory).
 */
abstract contract UniswapV4SingleStandardExchangeBufferConstantProductHookWithdrawTarget {
    using BetterSafeERC20 for IERC20;

    event Deposit(address indexed sender, address indexed to, uint256 amount0, uint256 amount1, uint256 used0, uint256 used1, uint256 lpAmount);
    event DepositSingle(address indexed sender, address indexed to, address tokenIn, uint256 amountIn, uint256 lpAmount);
    event Withdraw(address indexed sender, address indexed to, uint256 lpAmount, uint256 amount0, uint256 amount1);
    event WithdrawSingle(address indexed sender, address indexed to, uint256 lpAmount, address tokenOut, uint256 amountOut);
    event WithdrawSeShares(
        address indexed sender, address indexed to, uint256 lpAmount, uint256 amountRaw, uint256 amountSe
    );
    event ZapSwap(address indexed sender, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);

    address internal constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    error ZeroAddress();
    error ZeroAmount();
    error NotPoolManager();
    error TokenNotInVaultTokens();
    error SameToken();
    error RawIsSE();
    error NotLive();
    error NotZapEligible();
    error InvalidToken();
    error DeadlineExpired();
    error InsufficientLpOut();
    error InsufficientTokenOut();
    error AlreadyInitialized();
    error Reentrancy();
    error LiquidityNotAllowed();
    error InvalidPoolToken();
    error InvalidPoolFee();
    error HookNotImplemented();
    error UnsupportedRoute();

    modifier nonReentrant() {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (l.reentrancyStatus == UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.ENTERED) revert Reentrancy();
        l.reentrancyStatus = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.ENTERED;
        _;
        l.reentrancyStatus = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.NOT_ENTERED;
    }

    modifier onlyLiquidityOwner() {
        UniswapV4HookOwnerOnlyLiquidityLib.enforce(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().ownerOnlyLiquidity);
        _;
    }

    /* ---------------------------------------------------------------------- */
    /*                              bindings / views                          */
    /* ---------------------------------------------------------------------- */

    function poolManager() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().poolManager;
    }

    function feeOracle() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().feeOracle;
    }

    function permit2() public pure returns (address) {
        return PERMIT2;
    }

    function standardExchange() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().standardExchange;
    }

    function pairToken() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().pairToken;
    }

    function rawToken() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken;
    }

    function currency0() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency0;
    }

    function currency1() public view returns (address) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency1;
    }

    function rawReserve() public view returns (uint256) {
        return IERC20(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken).balanceOf(address(this));
    }

    function seClaimSupply() public view returns (uint256) {
        return _seClaim();
    }

    function reserveCurrency0() public view returns (uint256) {
        return _reserveOfCurrency(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency0);
    }

    function reserveCurrency1() public view returns (uint256) {
        return _reserveOfCurrency(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency1);
    }

    function isLive() public view returns (bool) {
        return _isLive();
    }

    function isZapEligible() public view returns (bool) {
        return _isZapEligible();
    }

    function tradingFeePercent() public pure returns (uint256) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.TRADING_FEE_PERCENT;
    }

    function tradingFeeDenominator() public pure returns (uint256) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.TRADING_FEE_DENOMINATOR;
    }

    function dexSwapFeeAndFeeTo() public view returns (address feeTo_, uint256 dexFeeWad) {
        (IFeeCollectorProxy ft, uint256 wad) =
            IVaultFeeOracleQuery(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().feeOracle).dexSwapFeeAndFeeToOfVault(address(this));
        return (address(ft), wad);
    }

    function kLast() public view returns (uint256) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().kLast;
    }

    function _seClaim() internal view returns (uint256) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 seBal = IERC20(l.standardExchange).balanceOf(address(this));
        if (seBal == 0) return 0;
        return IStandardExchangeIn(l.standardExchange).previewExchangeIn(
            IERC20(l.standardExchange), seBal, IERC20(l.pairToken)
        );
    }

    function _reserveOfCurrency(address c) internal view returns (uint256) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (c == l.rawToken) return IERC20(l.rawToken).balanceOf(address(this));
        if (c == l.pairToken) return _seClaim();
        return 0;
    }

    function _isLive() internal view returns (bool) {
        return reserveCurrency0() > 0 && reserveCurrency1() > 0;
    }

    function _isZapEligible() internal view returns (bool) {
        return _isLive() && ERC20Repo._totalSupply() > UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.MINIMUM_LIQUIDITY;
    }

    /// @dev Keep MultiAssetBasicVaultRepo reserves aligned with product book (raw face × virtual pair).
    function _syncReserves() internal {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        MultiAssetBasicVaultRepo._updateReserve(IERC20(l.rawToken), IERC20(l.rawToken).balanceOf(address(this)));
        MultiAssetBasicVaultRepo._updateReserve(IERC20(l.pairToken), _seClaim());
    }

    function _mintLp(address to, uint256 amount) internal {
        if (amount == 0) return;
        ERC20Repo._mint(to, amount);
    }

    function _burnLp(address from, uint256 amount) internal {
        ERC20Repo._burn(from, amount);
    }

    function _onlyPoolManager() internal view {
        if (msg.sender != UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().poolManager) revert NotPoolManager();
    }

    function _requireLive() internal view {
        if (!_isLive()) revert NotLive();
    }

    function _requireZapEligible() internal view {
        if (!_isZapEligible()) revert NotZapEligible();
    }

    function _requireNonZero(uint256 amount) internal pure {
        if (amount == 0) revert ZeroAmount();
    }

    function _requireDeadline(uint256 deadline) internal view {
        if (block.timestamp > deadline) revert DeadlineExpired();
    }

    function _decimalsOf(address token) internal view returns (uint8) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (token == l.currency0) return l.decimalsCurrency0;
        if (token == l.currency1) return l.decimalsCurrency1;
        revert InvalidToken();
    }

    function _wadProduct() internal view returns (uint256) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(reserveCurrency0(), UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().decimalsCurrency0)
            * UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(reserveCurrency1(), UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().decimalsCurrency1);
    }

    function _feeOnAndShare()
        internal
        view
        returns (bool feeOn, address feeTo_, uint256 ownerFeeShare)
    {
        uint256 dexFeeWad;
        (feeTo_, dexFeeWad) = dexSwapFeeAndFeeTo();
        feeOn = feeTo_ != address(0) && dexFeeWad != 0;
        ownerFeeShare = (dexFeeWad * UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.TRADING_FEE_DENOMINATOR) / 1e18;
    }

    function _previewBufferClaimIn(uint256 amountInRaw) internal view returns (uint256) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        return UniswapV4SingleStandardExchangeBufferConstantProductHookClaimLib.previewBufferClaimIn(
            l.standardExchange,
            l.pairToken,
            amountInRaw,
            IVaultFeeOracleQuery(l.feeOracle),
            address(this)
        );
    }

    function _invertBufferClaimIn(uint256 claimInNeeded) internal view returns (uint256) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        return UniswapV4SingleStandardExchangeBufferConstantProductHookClaimLib.invertBufferClaimIn(
            l.standardExchange,
            l.pairToken,
            claimInNeeded,
            IVaultFeeOracleQuery(l.feeOracle),
            address(this)
        );
    }

    /* ---------------------------------------------------------------------- */
    /*                              SE buffer / unwrap                        */
    /* ---------------------------------------------------------------------- */

    function _bufferPair(uint256 amount) internal returns (uint256 seOut) {
        _requireNonZero(amount);
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 minOut = IStandardExchangeIn(l.standardExchange).previewExchangeIn(
            IERC20(l.pairToken), amount, IERC20(l.standardExchange)
        );
        IERC20(l.pairToken).forceApprove(l.standardExchange, amount);
        seOut = IStandardExchangeIn(l.standardExchange).exchangeIn(
            IERC20(l.pairToken),
            amount,
            IERC20(l.standardExchange),
            minOut,
            address(this),
            false,
            block.timestamp
        );
    }

    function _unwrapSeShares(uint256 seIn) internal returns (uint256 pairOut) {
        _requireNonZero(seIn);
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 minOut = IStandardExchangeIn(l.standardExchange).previewExchangeIn(
            IERC20(l.standardExchange), seIn, IERC20(l.pairToken)
        );
        pairOut = IStandardExchangeIn(l.standardExchange).exchangeIn(
            IERC20(l.standardExchange),
            seIn,
            IERC20(l.pairToken),
            minOut,
            address(this),
            false,
            block.timestamp
        );
    }

    function _unwrapExactPairOut(uint256 pairOut) internal returns (uint256 seIn) {
        _requireNonZero(pairOut);
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        seIn = IStandardExchangeOut(l.standardExchange).previewExchangeOut(
            IERC20(l.standardExchange), IERC20(l.pairToken), pairOut
        );
        uint256 spent = IStandardExchangeOut(l.standardExchange).exchangeOut(
            IERC20(l.standardExchange),
            seIn,
            IERC20(l.pairToken),
            pairOut,
            address(this),
            false,
            block.timestamp
        );
        require(spent == seIn, "unwrap exact-out");
    }

    function _refundPairDust(address to) internal {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 bal = IERC20(l.pairToken).balanceOf(address(this));
        if (bal > UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.MAX_DUST_WEI) {
            IERC20(l.pairToken).safeTransfer(to, bal);
        }
    }

    /* ---------------------------------------------------------------------- */
    /*                              swap core                                 */
    /* ---------------------------------------------------------------------- */

    function _zeroForOneIsRawIn() internal view returns (bool) {
        return UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency0 == UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken;
    }

    function _quoteExactIn(bool zeroForOne, uint256 amountIn) internal view returns (uint256 amountOut) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        bool rawIn = zeroForOne == _zeroForOneIsRawIn();
        uint256 rawBal = IERC20(l.rawToken).balanceOf(address(this));
        uint256 seClaim = _seClaim();
        if (rawIn) {
            // face raw in → claim/pair out
            uint256 rInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawBal, _decimalsOf(l.rawToken));
            uint256 rOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(seClaim, _decimalsOf(l.pairToken));
            uint256 aInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(amountIn, _decimalsOf(l.rawToken));
            amountOut = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadFloor(UniswapV4SingleStandardExchangeBufferConstantProductHookMath.saleQuote(aInN, rInN, rOutN), _decimalsOf(l.pairToken));
        } else {
            // pair in → claimIn → raw out
            uint256 claimIn = _previewBufferClaimIn(amountIn);
            uint256 rInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(seClaim, _decimalsOf(l.pairToken));
            uint256 rOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawBal, _decimalsOf(l.rawToken));
            uint256 cInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(claimIn, _decimalsOf(l.pairToken));
            amountOut = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadFloor(UniswapV4SingleStandardExchangeBufferConstantProductHookMath.saleQuote(cInN, rInN, rOutN), _decimalsOf(l.rawToken));
        }
    }

    function _quoteExactOut(bool zeroForOne, uint256 amountOut) internal view returns (uint256 amountIn) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        bool rawIn = zeroForOne == _zeroForOneIsRawIn();
        uint256 rawBal = IERC20(l.rawToken).balanceOf(address(this));
        uint256 seClaim = _seClaim();
        if (rawIn) {
            // need pair out → raw in
            uint256 claimOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(amountOut, _decimalsOf(l.pairToken));
            uint256 rInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawBal, _decimalsOf(l.rawToken));
            uint256 rOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(seClaim, _decimalsOf(l.pairToken));
            amountIn = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadCeil(UniswapV4SingleStandardExchangeBufferConstantProductHookMath.purchaseQuote(claimOutN, rInN, rOutN), _decimalsOf(l.rawToken));
        } else {
            // need raw out → claimIn → invert buffer
            uint256 rawOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(amountOut, _decimalsOf(l.rawToken));
            uint256 rInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(seClaim, _decimalsOf(l.pairToken));
            uint256 rOutN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawBal, _decimalsOf(l.rawToken));
            uint256 claimInN = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.purchaseQuote(rawOutN, rInN, rOutN);
            uint256 claimIn = UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadCeil(claimInN, _decimalsOf(l.pairToken));
            amountIn = _invertBufferClaimIn(claimIn);
        }
    }
    function _routeZeroForOne(address tokenIn, address tokenOut) internal view returns (bool) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (tokenIn == l.currency0 && tokenOut == l.currency1) return true;
        if (tokenIn == l.currency1 && tokenOut == l.currency0) return false;
        revert UnsupportedRoute();
    }

    function withdraw(uint256 lpAmount, address to, uint256 minAmount0, uint256 minAmount1, uint256 deadline)
        external
        onlyLiquidityOwner
        nonReentrant
        returns (uint256 amount0, uint256 amount1)
    {
        return _withdraw(lpAmount, to, minAmount0, minAmount1, deadline);
    }

    function withdrawSingle(
        uint256 lpAmount,
        address tokenOut,
        address to,
        uint256 minAmountOut,
        uint256 deadline
    ) external onlyLiquidityOwner nonReentrant returns (uint256 amountOut) {
        return _withdrawSingle(lpAmount, tokenOut, to, minAmountOut, deadline);
    }

    /// @notice B6: proportional withdraw paying rawToken + SE vault shares (no unwrap).
    function withdrawSeShares(
        uint256 lpAmount,
        address to,
        uint256 minAmountRaw,
        uint256 minAmountSe,
        uint256 deadline
    ) external onlyLiquidityOwner nonReentrant returns (uint256 amountRaw, uint256 amountSe) {
        return _withdrawSeShares(lpAmount, to, minAmountRaw, minAmountSe, deadline);
    }

    function _withdraw(
        uint256 lpAmount,
        address to,
        uint256 minAmount0,
        uint256 minAmount1,
        uint256 deadline
    ) internal returns (uint256 amount0, uint256 amount1) {
        _requireDeadline(deadline);
        _requireNonZero(lpAmount);
        _mintProtocolFeeIfNeeded();

        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (lpAmount > ERC20Repo._balanceOf(msg.sender)) revert InsufficientLpOut();

        (uint256 rawOut, uint256 seOut) = _proRataRawAndSe(lpAmount);
        _burnLp(msg.sender, lpAmount);
        uint256 pairOut = seOut > 0 ? _unwrapSeShares(seOut) : 0;
        (amount0, amount1) = _orderAmounts(rawOut, pairOut);

        if (rawOut > 0) IERC20(l.rawToken).safeTransfer(to, rawOut);
        if (pairOut > 0) IERC20(l.pairToken).safeTransfer(to, pairOut);

        if (amount0 < minAmount0 || amount1 < minAmount1) revert InsufficientTokenOut();
        _syncReserves();
        _setKLastPostOp();
        _refundPairDust(msg.sender);
        emit Withdraw(msg.sender, to, lpAmount, amount0, amount1);
    }

    function _proRataRawAndSe(uint256 lpAmount) internal view returns (uint256 rawOut, uint256 seOut) {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 supply = ERC20Repo._totalSupply();
        rawOut = (IERC20(l.rawToken).balanceOf(address(this)) * lpAmount) / supply;
        seOut = (IERC20(l.standardExchange).balanceOf(address(this)) * lpAmount) / supply;
    }

    function _withdrawSeShares(
        uint256 lpAmount,
        address to,
        uint256 minAmountRaw,
        uint256 minAmountSe,
        uint256 deadline
    ) internal returns (uint256 amountRaw, uint256 amountSe) {
        _requireDeadline(deadline);
        _requireNonZero(lpAmount);
        _mintProtocolFeeIfNeeded();

        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (lpAmount > ERC20Repo._balanceOf(msg.sender)) revert InsufficientLpOut();

        (amountRaw, amountSe) = _proRataRawAndSe(lpAmount);
        _burnLp(msg.sender, lpAmount);

        if (amountRaw > 0) IERC20(l.rawToken).safeTransfer(to, amountRaw);
        if (amountSe > 0) IERC20(l.standardExchange).safeTransfer(to, amountSe);

        if (amountRaw < minAmountRaw || amountSe < minAmountSe) revert InsufficientTokenOut();
        _syncReserves();
        _setKLastPostOp();
        _refundPairDust(msg.sender);
        emit WithdrawSeShares(msg.sender, to, lpAmount, amountRaw, amountSe);
    }

    function _orderAmounts(uint256 rawAmt, uint256 pairAmt)
        internal
        view
        returns (uint256 amount0, uint256 amount1)
    {
        if (UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().currency0 == UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken) {
            amount0 = rawAmt;
            amount1 = pairAmt;
        } else {
            amount0 = pairAmt;
            amount1 = rawAmt;
        }
    }

    function _withdrawSingle(
        uint256 lpAmount,
        address tokenOut,
        address to,
        uint256 minAmountOut,
        uint256 deadline
    ) internal returns (uint256 amountOut) {
        _requireDeadline(deadline);
        _requireNonZero(lpAmount);
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (tokenOut != l.rawToken && tokenOut != l.pairToken) revert InvalidToken();
        _requireZapEligible();
        _mintProtocolFeeIfNeeded();

        if (lpAmount > ERC20Repo._balanceOf(msg.sender)) revert InsufficientLpOut();

        // O13: quote residual sell once on pre-buffer / pre-unwrap book (same as previewWithdrawSingle).
        amountOut = _previewWithdrawSingleAfterFeeMint(lpAmount, tokenOut);
        if (amountOut < minAmountOut) revert InsufficientTokenOut();

        uint256 supply = ERC20Repo._totalSupply();
        uint256 rawUser = (IERC20(l.rawToken).balanceOf(address(this)) * lpAmount) / supply;
        uint256 seUser = (IERC20(l.standardExchange).balanceOf(address(this)) * lpAmount) / supply;
        _burnLp(msg.sender, lpAmount);

        uint256 pairUser = seUser > 0 ? _unwrapSeShares(seUser) : 0;
        if (tokenOut == l.pairToken) {
            // Realize residual raw → pair using closed-form amount already quoted.
            uint256 residual = amountOut > pairUser ? amountOut - pairUser : 0;
            if (residual > 0) {
                _unwrapExactPairOut(residual);
                emit ZapSwap(msg.sender, l.rawToken, l.pairToken, rawUser, residual);
            }
            if (amountOut > 0) IERC20(l.pairToken).safeTransfer(to, amountOut);
        } else {
            // Realize residual pair → raw: buffer pair last after quote (O13).
            uint256 residual = amountOut > rawUser ? amountOut - rawUser : 0;
            if (pairUser > 0) {
                _bufferPair(pairUser);
                emit ZapSwap(msg.sender, l.pairToken, l.rawToken, pairUser, residual);
            }
            if (amountOut > 0) IERC20(l.rawToken).safeTransfer(to, amountOut);
        }

        _syncReserves();
        _setKLastPostOp();
        _refundPairDust(msg.sender);
        emit WithdrawSingle(msg.sender, to, lpAmount, tokenOut, amountOut);
    }

    /// @dev Shared preview/exec quote for zap-out after protocol mint (if any).
    function _previewWithdrawSingleAfterFeeMint(uint256 lpAmount, address tokenOut)
        internal
        view
        returns (uint256 amountOut)
    {
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 supply = ERC20Repo._totalSupply();
        if (lpAmount == 0 || supply == 0) return 0;
        uint256 rawBal = IERC20(l.rawToken).balanceOf(address(this));
        uint256 seBal = IERC20(l.standardExchange).balanceOf(address(this));
        uint256 rawUser = (rawBal * lpAmount) / supply;
        uint256 seUser = (seBal * lpAmount) / supply;
        uint256 pairUser = seUser == 0 ? 0 : _previewUnwrapSe(seUser);
        uint256 rawRemain = rawBal - rawUser;
        uint256 seClaimRem = _previewSeClaimOf(seBal - seUser);

        if (tokenOut == l.pairToken) {
            return pairUser + _saleQuoteRawToPair(rawUser, rawRemain, seClaimRem);
        }
        if (tokenOut == l.rawToken) {
            return rawUser + _saleQuotePairToRaw(pairUser, seClaimRem, rawRemain);
        }
        revert InvalidToken();
    }

    /* ---------------------------------------------------------------------- */
    /*                              protocol fee                              */
    /* ---------------------------------------------------------------------- */

    function _mintProtocolFeeIfNeeded() internal {
        (bool feeOn, address feeTo_, uint256 ownerFeeShare) = _feeOnAndShare();
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        if (!feeOn) {
            l.kLast = 0;
            return;
        }
        uint256 kLast_ = l.kLast;
        if (kLast_ == 0) return;
        uint256 protocolLp =
            UniswapV4SingleStandardExchangeBufferConstantProductHookMath.calculateProtocolFee(ERC20Repo._totalSupply(), _wadProduct(), kLast_, ownerFeeShare);
        if (protocolLp > 0) _mintLp(feeTo_, protocolLp);
    }

    function _setKLastPostOp() internal {
        (bool feeOn,,) = _feeOnAndShare();
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().kLast = feeOn ? _wadProduct() : 0;
    }

    function _supplyAfterProtocolMint() internal view returns (uint256 supplyAdj) {
        supplyAdj = ERC20Repo._totalSupply();
        (bool feeOn,, uint256 ownerFeeShare) = _feeOnAndShare();
        uint256 kLast_ = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().kLast;
        if (feeOn && kLast_ != 0 && supplyAdj > 0) {
            supplyAdj += UniswapV4SingleStandardExchangeBufferConstantProductHookMath.calculateProtocolFee(supplyAdj, _wadProduct(), kLast_, ownerFeeShare);
        }
    }

    /* ---------------------------------------------------------------------- */
    function previewWithdraw(uint256 lpAmount)
        external
        view
        returns (uint256 amount0, uint256 amount1)
    {
        uint256 supply = _supplyAfterProtocolMint();
        if (lpAmount == 0 || supply == 0) return (0, 0);
        // Preview uses post-protocol-mint supply; inventory split uses current balances.
        if (ERC20Repo._totalSupply() == 0) return (0, 0);
        uint256 rawOut =
            (IERC20(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken).balanceOf(address(this)) * lpAmount) / supply;
        uint256 seOut =
            (IERC20(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().standardExchange).balanceOf(address(this)) * lpAmount) / supply;
        return _orderAmounts(rawOut, seOut == 0 ? 0 : _previewUnwrapSe(seOut));
    }

    /// @notice B6 preview: pro-rata raw + SE shares (no unwrap).
    function previewWithdrawSeShares(uint256 lpAmount)
        external
        view
        returns (uint256 amountRaw, uint256 amountSe)
    {
        uint256 supply = _supplyAfterProtocolMint();
        if (lpAmount == 0 || supply == 0) return (0, 0);
        if (ERC20Repo._totalSupply() == 0) return (0, 0);
        amountRaw = (IERC20(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken).balanceOf(address(this)) * lpAmount) / supply;
        amountSe =
            (IERC20(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().standardExchange).balanceOf(address(this)) * lpAmount) / supply;
    }

    function previewWithdrawSingle(uint256 lpAmount, address tokenOut)
        external
        view
        returns (uint256 amountOut)
    {
        // Mirror exec: use post-protocol-mint supply for pro-rata weights when fee-on would mint.
        uint256 supplyNow = ERC20Repo._totalSupply();
        if (lpAmount == 0 || supplyNow == 0) return 0;
        // Temporarily view-simulate protocol mint by using adjusted supply only in pro-rata.
        // Exec mints first then divides by post-mint supply — same as _supplyAfterProtocolMint.
        // Inventory amounts still taken from current balances (protocol mint is LP-only).
        uint256 supply = _supplyAfterProtocolMint();
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        uint256 rawBal = IERC20(l.rawToken).balanceOf(address(this));
        uint256 seBal = IERC20(l.standardExchange).balanceOf(address(this));
        uint256 rawUser = (rawBal * lpAmount) / supply;
        uint256 seUser = (seBal * lpAmount) / supply;
        uint256 pairUser = seUser == 0 ? 0 : _previewUnwrapSe(seUser);
        uint256 rawRemain = rawBal - rawUser;
        uint256 seClaimRem = _previewSeClaimOf(seBal - seUser);

        if (tokenOut == l.pairToken) {
            return pairUser + _saleQuoteRawToPair(rawUser, rawRemain, seClaimRem);
        }
        if (tokenOut == l.rawToken) {
            return rawUser + _saleQuotePairToRaw(pairUser, seClaimRem, rawRemain);
        }
        revert InvalidToken();
    }

    function _previewUnwrapSe(uint256 seAmount) internal view returns (uint256) {
        if (seAmount == 0) return 0;
        UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.Layout storage l = UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout();
        return IStandardExchangeIn(l.standardExchange).previewExchangeIn(
            IERC20(l.standardExchange), seAmount, IERC20(l.pairToken)
        );
    }

    function _previewSeClaimOf(uint256 seBal) internal view returns (uint256) {
        if (seBal == 0) return 0;
        return _previewUnwrapSe(seBal);
    }

    function _saleQuoteRawToPair(uint256 rawIn, uint256 rawRes, uint256 pairRes)
        internal
        view
        returns (uint256)
    {
        if (rawIn == 0 || rawRes == 0 || pairRes == 0) return 0;
        uint8 dRaw = _decimalsOf(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken);
        uint8 dPair = _decimalsOf(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().pairToken);
        return UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadFloor(
            UniswapV4SingleStandardExchangeBufferConstantProductHookMath.saleQuote(UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawIn, dRaw), UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawRes, dRaw), UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(pairRes, dPair)),
            dPair
        );
    }

    function _saleQuotePairToRaw(uint256 pairIn, uint256 pairRes, uint256 rawRes)
        internal
        view
        returns (uint256)
    {
        if (pairIn == 0 || pairRes == 0 || rawRes == 0) return 0;
        uint256 claimIn = _previewBufferClaimIn(pairIn);
        uint8 dRaw = _decimalsOf(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().rawToken);
        uint8 dPair = _decimalsOf(UniswapV4SingleStandardExchangeBufferConstantProductHookRepo._layout().pairToken);
        return UniswapV4SingleStandardExchangeBufferConstantProductHookMath.fromWadFloor(
            UniswapV4SingleStandardExchangeBufferConstantProductHookMath.saleQuote(UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(claimIn, dPair), UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(pairRes, dPair), UniswapV4SingleStandardExchangeBufferConstantProductHookMath.toWad(rawRes, dRaw)),
            dRaw
        );
    }

    // LP ERC-20, IBasicVault, IStandardVault: shared diamond facets only.
}

